            for(int variant=0;variant<8;variant++){var cell=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,SizeFlagsVertical=Control.SizeFlags.ExpandFill};grid.AddChild(cell);var portrait=new PlanetPortrait{CustomMinimumSize=new(360,360),RenderSize=new(256,256),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,SizeFlagsVertical=Control.SizeFlags.ExpandFill};cell.AddChild(portrait);portrait.Configure(styles,cache);var descriptor=new PlanetAppearanceDescriptor(1,variant,1201488599727174231UL);var planet=new KnownPlanetView(new(1000+variant),variant+1,type,0,0,0,true,null,null){EnvironmentId=environment,Appearance=descriptor};portrait.ShowPlanet(planet);cell.AddChild(new Label{Text=$"Signature {variant+1}",HorizontalAlignment=HorizontalAlignment.Center});hashes.Add(Pixels(Descendants<TextureRect>(portrait).Single().Texture!));}
